import java.util.*;

class Solution {
    public String sharedPrefix(String[] words) {
        String first = words[0];
        for (int i = 0; i < first.length(); i++) {
            char c = first.charAt(i);
            for (int k = 1; k < words.length; k++) {
                // stop when a word runs out or disagrees at column i
                if (i == words[k].length() || words[k].charAt(i) != c) {
                    return first.substring(0, i);
                }
            }
        }
        return first; // every column of the first word matched
    }
}

